const S = 1000 / 360, px = c => [(C[c].lo + 180) * S, (84 - C[c].la) * S];

function bfs(s) { const d = { [s]: 0 }, p = {}, q = [s]; while (q.length) { const x = q.shift(); ADJ[x].forEach(y => { if (!(y in d)) { d[y] = d[x] + 1; p[y] = x; q.push(y) } }) } return { d, p } }
function shortest(s, t) { const { p } = bfs(s), r = [t]; while (r[0] !== s) r.unshift(p[r[0]]); return r }

let start, target, chain, par, mistakes, over, shown;
function newPuzzle() {
    const [lo, hi] = $("diff").value.split(",").map(Number);
    for (let i = 0; i < 500; i++) {
        const s = NAMES[Math.floor(Math.random() * NAMES.length)], { d } = bfs(s);
        const c = NAMES.filter(n => d[n] >= lo && d[n] <= hi);
        if (c.length) { start = s; target = c[Math.floor(Math.random() * c.length)]; par = d[target]; break }
    }
    chain = [start]; mistakes = 0; over = false; shown = null;
    $("sName").textContent = start; $("tName").textContent = target;
    $("par").textContent = "Shortest route: " + par + " steps";
    $("inp").value = ""; $("sugg").innerHTML = ""; say(""); lock(false); draw();
}
function say(t, c) { $("msg").textContent = t; $("msg").className = c || "" }
