    let h = "";
    if ($("all").checked) EDGES.forEach(([a, b, s]) => segs(a, b).forEach(([x1, y1, x2, y2]) => { h += `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" ${v} stroke="var(--dot)" stroke-opacity=".6" stroke-width="1"${s ? ' stroke-dasharray="3 3"' : ''}/>` }));
