function vb(e) { const r = $("map").getBoundingClientRect(); return [(e.clientX - r.left) * W / r.width, (e.clientY - r.top) * W / r.width] }
function zoomAt(f, x, y) { const k = Math.min(14, Math.max(1, view.k * f)); f = k / view.k; if (f === 1) return; view.tx = x - (x - view.tx) * f; view.ty = y - (y - view.ty) * f; view.k = k; applyView(); draw() }
